{
  "id": "18afffae-85c1-4718-850c-69e777564309",
  "version": "1.8",
  "name": "BellevueWeather",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "54aecc02-f903-4122-a41a-224347e139ce",
        "isDefaultEntryPoint": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      }
    },
    {
      "id": "fetchWeather",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Fetch Simulated Weather"
      },
      "inputs": {
        "script": "// Simulated Bellevue, WA weather scenarios weighted to match Pacific Northwest climate\nvar scenarios = [\n  { condition: 'Sunny',         temperatureF: 78, humidityPct: 35, windMph: 8,  uvIndex: 6 },\n  { condition: 'Partly Cloudy', temperatureF: 65, humidityPct: 55, windMph: 10, uvIndex: 4 },\n  { condition: 'Overcast',      temperatureF: 58, humidityPct: 70, windMph: 12, uvIndex: 2 },\n  { condition: 'Light Rain',    temperatureF: 52, humidityPct: 80, windMph: 9,  uvIndex: 1 },\n  { condition: 'Heavy Rain',    temperatureF: 48, humidityPct: 90, windMph: 18, uvIndex: 0 },\n  { condition: 'Thunderstorm',  temperatureF: 55, humidityPct: 88, windMph: 25, uvIndex: 0 },\n  { condition: 'Foggy',         temperatureF: 50, humidityPct: 85, windMph: 5,  uvIndex: 1 },\n  { condition: 'Snowy',         temperatureF: 34, humidityPct: 75, windMph: 10, uvIndex: 1 },\n  { condition: 'Windy',         temperatureF: 60, humidityPct: 50, windMph: 32, uvIndex: 3 },\n  { condition: 'Clear',         temperatureF: 82, humidityPct: 30, windMph: 5,  uvIndex: 8 }\n];\nvar weights = [10, 15, 15, 20, 10, 5, 8, 3, 4, 10];\nvar totalWeight = weights.reduce(function(s, w) { return s + w; }, 0);\nvar rand = Math.random() * totalWeight;\nvar cumulative = 0;\nvar picked = scenarios[0];\nfor (var i = 0; i < scenarios.length; i++) {\n  cumulative += weights[i];\n  if (rand < cumulative) { picked = scenarios[i]; break; }\n}\nreturn { weather: picked, city: 'Bellevue, WA' };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "evaluateDay",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate Day Quality"
      },
      "inputs": {
        "script": "var w = $vars.fetchWeather.output.weather;\nvar score = 50;\nvar reasons = [];\n// Condition score\nvar goodConditions = ['Sunny', 'Partly Cloudy', 'Clear', 'Windy'];\nvar badConditions  = ['Heavy Rain', 'Thunderstorm', 'Snowy'];\nif (goodConditions.indexOf(w.condition) !== -1) {\n  score += 20;\n  reasons.push(w.condition + ' skies');\n} else if (badConditions.indexOf(w.condition) !== -1) {\n  score -= 25;\n  reasons.push(w.condition + ' - not great for being outside');\n} else {\n  reasons.push(w.condition + ' conditions - manageable');\n}\n// Temperature score\nif (w.temperatureF >= 60 && w.temperatureF <= 80) {\n  score += 15;\n  reasons.push('Comfortable temperature (' + w.temperatureF + '°F)');\n} else if (w.temperatureF < 40) {\n  score -= 15;\n  reasons.push('Pretty cold at ' + w.temperatureF + '°F');\n} else if (w.temperatureF > 90) {\n  score -= 10;\n  reasons.push('Hot at ' + w.temperatureF + '°F - stay hydrated');\n} else {\n  reasons.push('Temperature is ' + w.temperatureF + '°F - okay');\n}\n// Wind score\nif (w.windMph > 25) {\n  score -= 15;\n  reasons.push('Very windy at ' + w.windMph + ' mph');\n} else if (w.windMph > 15) {\n  score -= 5;\n  reasons.push('Breezy at ' + w.windMph + ' mph');\n} else {\n  reasons.push('Calm winds (' + w.windMph + ' mph)');\n}\n// Humidity score\nif (w.humidityPct > 80) {\n  score -= 10;\n  reasons.push('High humidity (' + w.humidityPct + '%) feels muggy');\n} else if (w.humidityPct < 40) {\n  score += 5;\n  reasons.push('Low, comfortable humidity (' + w.humidityPct + '%)');\n}\n// Clamp 0-100\nif (score < 0) score = 0;\nif (score > 100) score = 100;\nreturn { score: score, reasons: reasons, weather: w };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "decideGoodOrNot",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Score >= 70?"
      },
      "inputs": {
        "expression": "=js:$vars.evaluateDay.output.score >= 70",
        "trueLabel": "Good Day",
        "falseLabel": "Not Great"
      }
    },
    {
      "id": "decideOkayOrBad",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Score >= 45?"
      },
      "inputs": {
        "expression": "=js:$vars.evaluateDay.output.score >= 45",
        "trueLabel": "Okay Day",
        "falseLabel": "Bad Day"
      }
    },
    {
      "id": "buildGoodReport",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Build Good Day Report"
      },
      "inputs": {
        "script": "var ev = $vars.evaluateDay.output;\nvar w  = ev.weather;\nreturn {\n  verdict: 'GOOD',\n  score:   ev.score,\n  city:    $vars.fetchWeather.output.city,\n  condition:     w.condition,\n  temperatureF:  w.temperatureF,\n  humidityPct:   w.humidityPct,\n  windMph:       w.windMph,\n  uvIndex:       w.uvIndex,\n  reasons:       ev.reasons,\n  summary:       \"It's a great day in Bellevue! Get outside and enjoy it.\"\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "buildOkayReport",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Build Okay Day Report"
      },
      "inputs": {
        "script": "var ev = $vars.evaluateDay.output;\nvar w  = ev.weather;\nreturn {\n  verdict: 'OKAY',\n  score:   ev.score,\n  city:    $vars.fetchWeather.output.city,\n  condition:     w.condition,\n  temperatureF:  w.temperatureF,\n  humidityPct:   w.humidityPct,\n  windMph:       w.windMph,\n  uvIndex:       w.uvIndex,\n  reasons:       ev.reasons,\n  summary:       \"It's a decent day in Bellevue - nothing to complain about.\"\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "buildBadReport",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Build Bad Day Report"
      },
      "inputs": {
        "script": "var ev = $vars.evaluateDay.output;\nvar w  = ev.weather;\nreturn {\n  verdict: 'BAD',\n  score:   ev.score,\n  city:    $vars.fetchWeather.output.city,\n  condition:     w.condition,\n  temperatureF:  w.temperatureF,\n  humidityPct:   w.humidityPct,\n  windMph:       w.windMph,\n  uvIndex:       w.uvIndex,\n  reasons:       ev.reasons,\n  summary:       \"Better stay indoors today. Not ideal weather in Bellevue.\"\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
